SELECT t.*, , if (t.MARKET_VALUE = '02', t.subno,null) prodAllAmt , if (t.MARKET_VALUE = '17', t.subno,null) totalValue , if (t.MARKET_VALUE = '05', t.subno,null) dailyAssetAllValue , if (t.MARKET_VALUE = '06', t.subno,null) dailyAllDebt , if (t.MARKET_VALUE = '08', t.subno,null) unitValue FROM ( SELECT DETAIL_DIST, BOOKSET_ID AS bookSetId, ( SELECT bb.ACCT_SUBJECT_ID FROM BOK_BOOKSET bb WHERE bb.BOOKSET_ID = BOK_VAL_TABLE_DATA.BOOKSET_ID) AS prodId, date_format(VAL_DATE,'%Y-%M-%D') AS valueDate, IFNULL(MARKET_VALUE, cast(REGEXP_REPLACE(BOK_VAL_TABLE_DATA.SUBJECT_NAME,'[^0-9|.]','')) as unsigned int ) MARKET_VALUE FROM BOK_VAL_TABLE_DATA WHERE BOOKSET_ID IN ( SELECT bookset_id FROM BOK_BOOKSET WHERE ACCT_MODE = '01') AND BOOKSET_ID in
#{item, jdbcType=VARCHAR}
AND VAL_DATE = #{exeDate, jdbcType=TIMESTAMP} AND DETAIL_DIST IN ('02','05','06','07','08','17') ) t ORDER BY t.valueDate
